131	// Unlike FetchURL:
132	//   - it derives protocol from the requested push remote, not always origin
133	//   - it skips checkpoint remote use when the push remote owner differs
134	//     from the configured checkpoint remote owner
135	//
136	// If ENTIRE_CHECKPOINT_TOKEN is set, HTTPS is forced so the token can be used
137	// even when the push remote is configured via SSH.
138	//
139	// The boolean return value reports whether a dedicated checkpoint_remote is
140	// configured and should be used for push. When false, the returned URL is the
141	// repository's origin URL as a fallback.
142	func PushURL(ctx context.Context, pushRemoteName string) (string, bool, error) {
143		originURL := ""
144		if resolvedOriginURL, err := GetRemoteURL(ctx, originRemote); err == nil {
145			originURL = resolvedOriginURL
146		}
147	
148		s, err := settings.Load(ctx)
149		if err != nil {
150			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
151			if fallbackErr == nil {
152				logFallback(ctx, "push", fallbackURL, "load settings", err,
153					slog.String("push_remote", pushRemoteName),
154				)
155				return fallbackURL, false, nil
156			}
157			return "", false, fmt.Errorf("load settings: %w", err)
158		}
159	
160		config := s.GetCheckpointRemote()
161		if config == nil {
162			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
163			if fallbackErr != nil {
164				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
165			}
166			return fallbackURL, false, nil
167		}
168	
169		pushRemoteURL, err := GetRemoteURL(ctx, pushRemoteName)
170		if err != nil {
171			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
172			if fallbackErr == nil {
173				logFallback(ctx, "push", fallbackURL, "get push remote URL", err,
174					slog.String("push_remote", pushRemoteName),
175				)
176				return fallbackURL, false, nil
177			}
178			return "", true, fmt.Errorf("no push URL found: %w", err)
179		}
180	
181		pushInfo, err := ParseURL(pushRemoteURL)
182		if err != nil {
183			if originURL != "" {
184				logFallback(ctx, "push", originURL, "parse push remote URL", err,
185					slog.String("push_remote", pushRemoteName),
186				)
187				return originURL, false, nil
188			}
189			return "", true, fmt.Errorf("no push URL found: %w", err)
190		}
191		withToken := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != ""
192		if withToken && isDirectGitTransport(pushInfo.Protocol) {
193			// Coerce a direct (ssh/https) remote to HTTPS so the token applies,
194			// keeping the host so enterprise installations stay on their own host.
195			// An entire:// remote carries a cluster host that isn't a usable HTTPS
196			// host, so it's handled separately after the owner check below.
197			//
198			// Keep the port only when the source was already HTTPS. SSH ports
199			// (e.g., :2222) don't map to HTTPS ports on the same host.
200			port := ""
201			if pushInfo.Protocol == ProtocolHTTPS {
202				port = pushInfo.Port
203			}
204			pushInfo = &Info{
205				Protocol: ProtocolHTTPS,
206				Host:     pushInfo.Host,
207				Port:     port,
208				Owner:    pushInfo.Owner,
209				Repo:     pushInfo.Repo,
210			}
211		}
212	
213		checkpointOwner := config.Owner()
214		if pushInfo.Owner != "" && checkpointOwner != "" && !strings.EqualFold(pushInfo.Owner, checkpointOwner) {
215			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
216			if fallbackErr != nil {
217				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
218			}
219			return fallbackURL, false, nil
220		}
221	
222		if withToken && pushInfo.Protocol == ProtocolEntire {
223			// The checkpoint token is an HTTPS credential for the provider host;
224			// it can't ride through the entire:// helper (which does its own
225			// auth). Route to the provider over HTTPS instead of the mirror.
226			if providerURL, ok := resolveProviderCheckpointURL(config, ""); ok {
227				return providerURL, true, nil
228			}
229		}
230	
231		pushURL, err := deriveCheckpointURLFromInfo(pushInfo, config)
232		if err != nil {
233			// The push remote's protocol can't be mapped to a checkpoint URL
234			// (e.g. file://, or an entire:// mirror of a different forge than the
235			// configured provider). Honor the configured checkpoint_remote by
236			// targeting the provider's canonical host over HTTPS rather than
237			// misrouting checkpoints to the origin remote.
238			if providerURL, ok := resolveProviderCheckpointURL(config, ""); ok {
239				return providerURL, true, nil
240			}
241			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
242			if fallbackErr == nil {
243				logFallback(ctx, "push", fallbackURL, "derive push checkpoint URL", err,
244					slog.String("push_remote", pushRemoteName),
245				)
246				return fallbackURL, false, nil
247			}
248			return "", true, fmt.Errorf("no push URL found: %w", err)
249		}
250	
251		return pushURL, true, nil
252	}
